/*
 * [算法說明]
 * 本題要求在給定的區間 [L, U] 內尋找距離最近與最遠的相鄰質數。
 * 由於 U 的範圍可達 2^31 - 1，我們無法對整個範圍進行篩選，但 U - L 的範圍不超過 1,000,000。
 * 1. 首先預先篩選出 sqrt(2^31-1) ≈ 46340 以內的所有質數。
 * 2. 對於每個查詢區間 [L, U]，使用區間篩法 (Segmented Sieve)：
 *    - 建立一個長度為 U - L + 1 的布林陣列，標記該區間內的數字是否為質數。
 *    - 使用預先篩出的質數 p，將區間內 p 的倍數標記為合數。
 *    - 注意：1 不是質數，且需確保不將質數 p 本身標記為合數（若 p 在區間內）。
 * 3. 收集區間內的所有質數，依次計算相鄰質數的距離，記錄最小值與最大值。
 */

#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

const int MAX_SQRT = 46341;
vector<int> base_primes;

void sieve_base() {
    vector<bool> is_prime(MAX_SQRT, true);
    is_prime[0] = is_prime[1] = false;
    for (int i = 2; i < MAX_SQRT; ++i) {
        if (is_prime[i]) {
            base_primes.push_back(i);
            for (long long j = (long long)i * i; j < MAX_SQRT; j += i)
                is_prime[j] = false;
        }
    }
}

int main() {
    sieve_base();
    long long L, U;
    while (cin >> L >> U) {
        vector<bool> is_prime_range(U - L + 1, true);
        if (L == 1) is_prime_range[0] = false;

        for (int p : base_primes) {
            if ((long long)p * p > U) break;
            long long start = (L + p - 1) / p * p;
            if (start == p) start += p;
            for (long long j = start; j <= U; j += p) {
                is_prime_range[j - L] = false;
            }
        }

        vector<long long> primes_in_range;
        for (long long i = L; i <= U; ++i) {
            if (is_prime_range[i - L]) {
                primes_in_range.push_back(i);
            }
        }

        if (primes_in_range.size() < 2) {
            cout << "There are no adjacent primes." << endl;
        } else {
            long long min_dist = LLONG_MAX, max_dist = -1;
            long long c1, c2, d1, d2;
            for (size_t i = 0; i < primes_in_range.size() - 1; ++i) {
                long long diff = primes_in_range[i + 1] - primes_in_range[i];
                if (diff < min_dist) {
                    min_dist = diff;
                    c1 = primes_in_range[i];
                    c2 = primes_in_range[i + 1];
                }
                if (diff > max_dist) {
                    max_dist = diff;
                    d1 = primes_in_range[i];
                    d2 = primes_in_range[i + 1];
                }
            }
            cout << c1 << "," << c2 << " are closest, " << d1 << "," << d2 << " are most distant." << endl;
        }
    }
    return 0;
}
